package com.gameaggregator.gameservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="taxonomies",uniqueConstraints=@UniqueConstraint(columnNames={"type","code"})) public class Taxonomy{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public String type;@Column(nullable=false)public String code;@Column(nullable=false)public String name;protected Taxonomy(){}public Taxonomy(String t,String c,String n){type=t;code=c;name=n;}}